create table public.mod_items (
  id uuid default gen_random_uuid() not null,
  car_id uuid not null,
  group_label text default 'Other'::text not null,
  category text,
  brand text,
  product text,
  part_number text,
  raw_text text,
  linked_listing_id uuid,
  confidence real,
  position integer default 0 not null,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  status text default 'installed'::text not null,
  removed_at timestamp with time zone,
  source_order_item_id uuid,
  product_url text,
  image_url text,
  source_domain text,
  ref_price_cents integer,
  ref_price_currency text,
  origin text default 'aftermarket'::text not null,
  part_number_compact text generated always as (NULLIF(regexp_replace(lower(COALESCE(part_number, ''::text)), '[^a-z0-9]'::text, ''::text, 'g'::text), ''::text)) stored,
  brand_key text generated always as (NULLIF(regexp_replace(lower(COALESCE(brand, ''::text)), '[^[:alnum:]]'::text, ''::text, 'g'::text), ''::text)) stored
);

alter table public.mod_items enable row level security;

-- Comments
comment on column public.mod_items.status is 'installed | removed. Removal is a state, not a delete: the row keeps its id so listings, updates and the public build sheet can still name the part.';
comment on column public.mod_items.removed_at is 'When the part came off. Set exactly when status = removed.';
comment on column public.mod_items.source_order_item_id is 'The order item this mod was built from (C-1). Unique, so adding a purchase to a car twice is a no-op.';
comment on column public.mod_items.product_url is 'Where the owner pasted this part from. Displayed as a plain link out; never used as a listing photo source.';
comment on column public.mod_items.image_url is 'Thumbnail imported from the product link, in DRVN storage. A shop product photo must never become a listing photo (L-4).';
comment on column public.mod_items.source_domain is 'Host the link came from, for the "via <shop>" line.';
comment on column public.mod_items.ref_price_cents is 'What the shop listed it at when the link was read. Reference only — not a DRVN price.';
comment on column public.mod_items.ref_price_currency is 'ISO-4217 code for ref_price_cents. No currency means no price: the check below refuses the ambiguous half-state.';
comment on column public.mod_items.origin is 'aftermarket (fitted by the owner) or stock (a factory part that came off when a mod went on).';
comment on column public.mod_items.part_number_compact is 'part_number lower-cased with every non a-z0-9 character removed (the listings.part_number_compact expression). Generated.';
comment on column public.mod_items.brand_key is 'brand lower-cased with everything but letters and digits removed ("-Bosch", "BOSCH" -> bosch). Generated; the products identity half.';

-- Constraints
alter table public.mod_items add constraint mod_items_car_id_fkey FOREIGN KEY (car_id) REFERENCES public.cars(id) ON DELETE CASCADE;
alter table public.mod_items add constraint mod_items_image_url_https CHECK (image_url IS NULL OR image_url ~ '^https://[^[:space:]]+$'::text);
alter table public.mod_items add constraint mod_items_linked_listing_id_fkey FOREIGN KEY (linked_listing_id) REFERENCES public.listings(id) ON DELETE SET NULL;
alter table public.mod_items add constraint mod_items_origin_check CHECK (origin = ANY (ARRAY['aftermarket'::text, 'stock'::text]));
alter table public.mod_items add constraint mod_items_pkey PRIMARY KEY (id);
alter table public.mod_items add constraint mod_items_product_url_http CHECK (product_url IS NULL OR product_url ~* '^https?://[^[:space:]]+$'::text);
alter table public.mod_items add constraint mod_items_ref_price_currency_check CHECK (ref_price_cents IS NULL OR ref_price_currency IS NOT NULL AND ref_price_cents >= 0);
alter table public.mod_items add constraint mod_items_removed_at_agrees_check CHECK ((status = 'removed'::text) = (removed_at IS NOT NULL));
alter table public.mod_items add constraint mod_items_source_domain_shape CHECK (source_domain IS NULL OR source_domain ~* '^[a-z0-9]([a-z0-9.-]{0,251}[a-z0-9])?$'::text);
alter table public.mod_items add constraint mod_items_source_order_item_id_fkey FOREIGN KEY (source_order_item_id) REFERENCES public.order_items(id) ON DELETE SET NULL;
alter table public.mod_items add constraint mod_items_status_check CHECK (status = ANY (ARRAY['installed'::text, 'removed'::text]));

-- Indexes
CREATE INDEX mod_items_car_idx ON public.mod_items USING btree (car_id);
CREATE INDEX mod_items_car_status_position_idx ON public.mod_items USING btree (car_id, status, "position");
CREATE INDEX mod_items_image_media_key_idx ON public.mod_items USING btree (private.media_object_key(image_url));
CREATE INDEX mod_items_linked_listing_idx ON public.mod_items USING btree (linked_listing_id) WHERE (linked_listing_id IS NOT NULL);
CREATE INDEX mod_items_part_key_idx ON public.mod_items USING btree (part_number_compact, brand_key) WHERE (part_number_compact IS NOT NULL);
CREATE INDEX mod_items_search_doc_trgm_idx ON public.mod_items USING gin (public.mod_search_doc(brand, product, part_number) public.gin_trgm_ops) WHERE (status = 'installed'::text);
CREATE UNIQUE INDEX mod_items_source_order_item_key ON public.mod_items USING btree (source_order_item_id) WHERE (source_order_item_id IS NOT NULL);

-- Grants
grant all on table public.mod_items to anon;
grant all on table public.mod_items to authenticated;
